-- Seed Vibe_Clusters

-- Seed Tracks

-- Seed Live_Queue for Main Stage with Cluster 1
SELECT 1, track_id, row_number() over (order by random()), 'QUEUED' 
FROM Tracks WHERE cluster_id = 1 LIMIT 5;

-- Set first track to PLAYING
UPDATE Live_Queue SET status = 'PLAYING' WHERE queue_id = (SELECT queue_id FROM Live_Queue ORDER BY play_order LIMIT 1);
